package tasks

import (
	"bytes"
	"fmt"
)

type Repo struct {
	CloneURL string
}

type Issue struct {
	Number  int
	HTMLURL string
	Title   string
	Body    string
}

type IssueComment struct {
	UserLogin string
	Body      string
}

type FixIssueParams struct {
	Repo          Repo
	Issue         Issue
	IssueComments []IssueComment
	Instruction   string
	Branch        string
	Models        []string
	DraftPR       bool
	// PRLabel is the comma-separated label set the PR must carry.
	PRLabel string
	NoPR    bool
	// TriggerLabel names the agent in the "generated by" line. It is kept
	// apart from PRLabel, which also carries the parent issue's labels and
	// so reads as e.g. "overseer,priority/medium,area/release".
	TriggerLabel string
	// Disclose asks for the "generated by" line in the PR description.
	Disclose bool
}

func GetFixIssueScript() ([]byte, error) {
	return getScriptWithDefaults("fix_issue.sh")
}

func RenderFixIssuePrompt(params FixIssueParams) ([]byte, error) {
	if len(params.Models) == 0 {
		params.Models = DefaultModels
	}

	promptTmpl, err := getPromptTemplate("fix_issue.txt")
	if err != nil {
		return nil, fmt.Errorf("getting prompt template: %w", err)
	}
	var pBuf bytes.Buffer
	if err := promptTmpl.Execute(&pBuf, params); err != nil {
		return nil, fmt.Errorf("executing prompt template: %w", err)
	}

	return pBuf.Bytes(), nil
}
